func importProgressTerminal(progress ui.ImportProgress) bool {
	if progress.Operation.State == "failed" || progress.Operation.State == "cancelled" {
		return true
	}
	if progress.Operation.State != "completed" {
		return false
	}
	if progress.Deployment == nil {
		return progress.Operation.OrchestrationJobID == nil
	}
	return progress.Deployment.Status == "completed" || deploymentFailed(*progress.Deployment)
}

func deploymentLabel(progress ui.ImportProgress) string {
	if progress.Deployment == nil {
		return "Waiting for committed orchestration job"
	}
	return progress.Deployment.Status + " / " + progress.Deployment.DeploymentState
}

func deploymentFailed(value store.ImportDeploymentStatus) bool {
	return value.Status == "failed" || value.Status == "cancelled" || value.Status == "superseded" || value.DeploymentState == "failed" || value.DeploymentState == "cancelled" || value.DeploymentState == "superseded"
}

func deploymentFailureGuidance(value store.ImportDeploymentStatus) string {
	code := ""
	if value.TerminalErrorCode != nil {
		code = *value.TerminalErrorCode
	}
	switch code {
	case "image_not_published":
		return "The workflow completed but the commit-tagged image was not published. Verify the workflow pushes the full commit SHA tag, then retry orchestration from the environment."
	case "image_digest_invalid", "oci_annotation_mismatch":
		return "OCI verification rejected the published artifact. Correct the image digest/source/revision metadata and retry artifact resolution."
	case "image_pull_secret_reconcile_failed":
		return "The private pull Secret is not ready in the production namespace. Open GHCR credential status, finish rotation/reconciliation, then retry deployment."
	default:
		return "The initial deployment did not complete. Open the production environment for the typed orchestration error and retry action."
	}
}

func importFailureGuidance(operation store.ImportOperation) string {
	code := ""
	if operation.FailureCode != nil {
		code = *operation.FailureCode
	}
	switch code {
	case "github_app_not_configured":
		return "Set up the singleton GitHub App in Git Connections, then retry."
	case "github_installation_suspended":
		return "Restore the suspended installation in GitHub, refresh access in Git Connections, then retry."
	case "github_installation_access_removed", "github_repository_access_removed":
		return "Refresh or reinstall GitHub access, then choose the discovered repository again."
	case "workflow_incompatible":
		return "The workflow changed or is incompatible. Discover workflows again and choose one marked compatible."
	case "registry_auth_required":
		return "Configure the first private GHCR credential during import, or verify the active credential status."
	case "registry_auth_failed":
		return "Rotate the GHCR credential with a username and PAT classic that can read every referenced private package."
	case "registry_credential_exists":
		return "An active GHCR credential already exists. Do not enter replacement credentials during import; use explicit rotation, then retry without secret fields."
	case "registry_credential_in_progress":
		return "A GHCR credential create or rotation is already running. Open credential status and retry after it reaches ready or failed."
	case "conflict":
		return "A project/application or idempotency identity conflicts with existing data. Keep the same form for a lost-response retry, or choose new names for a new import."
	case "failed_precondition":
		return "GitHub access or discovered repository state changed. Refresh Git Connections and rediscover the repository and workflow."
	case "invalid_argument":
		return "Review repository, workflow, names, tagless GHCR image, runtime values, and credential field pairing, then retry."
	default:
		return "The import did not complete. Review Git Connections and GHCR status; no credential value is retained or shown here."
	}
}

